-- qcm.blani theme -> document -> version hierarchy build
-- Snapshot taken first (pg_dump wwf_tasks_pre_hierarchy_*.dump). Nothing is locked.
BEGIN;
SELECT set_config('app.user_id', 'f61b6f0f-821a-44d9-ba46-a64f7ef34f44', true);
SELECT set_config('app.org_id', (SELECT org_id::text FROM tasks WHERE user_id='f61b6f0f-821a-44d9-ba46-a64f7ef34f44' LIMIT 1), true);
SELECT set_config('app.role', 'ADMIN', true);
SET LOCAL TIME ZONE 'Europe/Skopje';

-- idempotency guard: refuse to double-apply
DO $$ BEGIN IF EXISTS (SELECT 1 FROM tasks WHERE external_ref LIKE 'theme:%' AND is_deleted=false) THEN RAISE EXCEPTION 'theme parents already exist — aborting to avoid double-apply'; END IF; END $$;

